const e=JSON.parse(`[{"set_id":"LR_E8A_S1_5","exercise":"exercise_8a","type":"venn_diagrams","is_set":true,"setup_text":"In the diagram, the Circle represents all the people who like MAAZA, the Square represents all the people who like Thumbs Up, the Triangle represents all the people who like Marinda, and the Rectangle represents all the people who like Coca-Cola. Individual letters (r, v, s, t, w, u, y, x, z, a, b, p, q) mark the distinct overlap regions of the four shapes.","setup_solution":"Reading the diagram region by region: b lies in the Square-Rectangle overlap only (Thumbs Up and Coca-Cola, not Maaza or Marinda); u, y, x lie inside both the Circle and the Square; v and w lie inside the Circle and the Triangle; q lies inside the Rectangle only. These region reads are cross-checked against the answer key throughout this set.","entity_count":13,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["diagram_region_reading"],"questions":[{"id":"LR_E8A_Q001","question_text":"Which of the following represents the people who like coca-cola and Thumbs up?","options":{"A":"r","B":"u","C":"b","D":"q"},"correct_answer":"C","correct_answer_value":"b","solution_text":"Region b sits in the overlap of the Square (Thumbs Up) and Rectangle (Coca-Cola) only.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75,"question_image":"QIMG_LR_E8A_S1_5"},{"id":"LR_E8A_Q002","question_text":"Which of the following represents the people who like Marinda but not Thumbs up?","options":{"A":"v, s, w, x","B":"v, s, z, a","C":"v, w, x, a","D":"None of these"},"correct_answer":"D","correct_answer_value":"None of these","solution_text":"The regions that are inside the Triangle (Marinda) but outside the Square (Thumbs Up) are v, s, z and p -- none of the listed option-sets matches this combination exactly.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S1_5"},{"id":"LR_E8A_Q003","question_text":"Which of the following represents the people who like Maaza and Thumbs up?","options":{"A":"u, t, w","B":"v, w, x","C":"b, a, x","D":"u, y, x"},"correct_answer":"D","correct_answer_value":"u, y, x","solution_text":"Regions u, y and x all lie inside both the Circle (Maaza) and the Square (Thumbs Up).","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75,"question_image":"QIMG_LR_E8A_S1_5"},{"id":"LR_E8A_Q004","question_text":"Which of the following represents the people who like both Maaza and Marinda but not any of the other two?","options":{"A":"y","B":"v","C":"u","D":"None of these"},"correct_answer":"B","correct_answer_value":"v","solution_text":"Region v lies in the Circle-Triangle overlap only, outside both the Square and the Rectangle.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S1_5"},{"id":"LR_E8A_Q005","question_text":"Which of the following represents the people who like Marinda, Maaza, Coca-cola but not Thumbs up?","options":{"A":"b","B":"r","C":"s","D":"w"},"correct_answer":"D","correct_answer_value":"w","solution_text":"Region w lies inside the Circle, Triangle and Rectangle but outside the Square.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S1_5"}],"question_image":"QIMG_LR_E8A_S1_5"},{"set_id":"LR_E8A_S6_10","exercise":"exercise_8a","type":"venn_diagrams","is_set":true,"setup_text":"In the diagram, Circle I represents athletes who participated in Swimming, Circle II represents Running, Circle III represents Javelin throw, and Circle IV represents Long jump. Regions a through m mark the distinct overlaps of the four circles.","setup_solution":"Reading the four-ellipse layout: a=Swimming(I) only, c=Running(II) only, m=Long jump(IV) only, l=Javelin(III) only; b=I-II only, h=I-IV only, d=II-III only, k=III-IV only (the four two-way overlaps); g=I-II-IV, e=I-II-III, i=I-III-IV, j=II-III-IV (the four three-way overlaps); f=all four circles together.","entity_count":13,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["diagram_region_reading","set_operations"],"questions":[{"id":"LR_E8A_Q006","question_text":"Which of the following represents the athletes who participated neither in Running nor in Long jump?","options":{"A":"j, k","B":"c, d","C":"a, l","D":"k, l"},"correct_answer":"C","correct_answer_value":"a, l","solution_text":"Regions a (Swimming only) and l (Javelin only) are the only two regions that fall outside both Circle II (Running) and Circle IV (Long jump).","question_operation":"position_lookup","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S6_10"},{"id":"LR_E8A_Q007","question_text":"Which of the following represents the athletes who participated in Running and Swimming?","options":{"A":"a, h, b, g, e, f","B":"a, b, c","C":"g, e, f","D":"b, g, e, f"},"correct_answer":"D","correct_answer_value":"b, g, e, f","solution_text":"Regions b, g, e and f all lie within both Circle I (Swimming) and Circle II (Running).","question_operation":"position_lookup","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S6_10"},{"id":"LR_E8A_Q008","question_text":"Which of the following represents the athletes who participated in all the four events?","options":{"A":"g","B":"j","C":"i","D":"f"},"correct_answer":"D","correct_answer_value":"f","solution_text":"Region f is the single region common to all four circles.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S6_10"},{"id":"LR_E8A_Q009","question_text":"Which of the following represents the athletes who participated in exactly three of the four events?","options":{"A":"h, b, k, d","B":"g, e, i, j","C":"a, c, d, k","D":"f, j, k, i"},"correct_answer":"B","correct_answer_value":"g, e, i, j","solution_text":"Regions g, e, i and j are exactly the four three-way overlap regions (each missing one of the four events).","question_operation":"position_lookup","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S6_10"},{"id":"LR_E8A_Q010","question_text":"Which of the following represents the athletes who participated in Swimming and Javelin throw but not in Running?","options":{"A":"j","B":"g","C":"k","D":"i"},"correct_answer":"D","correct_answer_value":"i","solution_text":"Region i is the Swimming-Javelin-Long jump three-way overlap (I-III-IV), which includes Swimming and Javelin while excluding Running.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S6_10"}],"question_image":"QIMG_LR_E8A_S6_10"},{"set_id":"LR_E8A_S11_15","exercise":"exercise_8a","type":"venn_diagrams","is_set":true,"setup_text":"The following Venn diagram shows three overlapping groups: Singers, Engineers and Actors. The regions are: Singers only = 8, Singers-Engineers only = 9, Engineers only = 10, Singers-Actors only = 3, all three = 2, Engineers-Actors only = 21, Actors only = 20.","setup_solution":"Direct region reads and simple sums from the given diagram values: Singers-only=8, Singers-Engineers-only=9, Engineers-only=10, Singers-Actors-only=3, all-three=2, Engineers-Actors-only=21, Actors-only=20.","entity_count":3,"variables":1,"constraints":3,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["set_arithmetic"],"questions":[{"id":"LR_E8A_Q011","question_text":"How many Engineers are also Singers?","options":{"A":"15","B":"9","C":"11","D":"21"},"correct_answer":"C","correct_answer_value":"11","solution_text":"Engineers who are also Singers = (Singers-Engineers only, 9) + (all three, 2) = 11.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75,"question_image":"QIMG_LR_E8A_S11_15"},{"id":"LR_E8A_Q012","question_text":"How many Actors are not Engineers?","options":{"A":"24","B":"23","C":"15","D":"18"},"correct_answer":"B","correct_answer_value":"23","solution_text":"Actors who are not Engineers = (Actors only, 20) + (Singers-Actors only, 3) = 23.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75,"question_image":"QIMG_LR_E8A_S11_15"},{"id":"LR_E8A_Q013","question_text":"How many Singers are Actors but not Engineers?","options":{"A":"8","B":"3","C":"9","D":"21"},"correct_answer":"B","correct_answer_value":"3","solution_text":"This is exactly the Singers-Actors-only region = 3.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":60,"question_image":"QIMG_LR_E8A_S11_15"},{"id":"LR_E8A_Q014","question_text":"How many Engineers are either Singers or Actors but not both?","options":{"A":"25","B":"28","C":"35","D":"30"},"correct_answer":"D","correct_answer_value":"30","solution_text":"Engineers in exactly one of {Singers, Actors} = (Singers-Engineers only, 9) + (Engineers-Actors only, 21) = 30.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S11_15"},{"id":"LR_E8A_Q015","question_text":"How many Singers are Actors as well as Engineers?","options":{"A":"21","B":"9","C":"3","D":"2"},"correct_answer":"D","correct_answer_value":"2","solution_text":"This is the all-three region = 2.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":60,"question_image":"QIMG_LR_E8A_S11_15"}],"question_image":"QIMG_LR_E8A_S11_15"},{"set_id":"LR_E8A_S16_20","exercise":"exercise_8a","type":"venn_diagrams","is_set":true,"setup_text":"The Venn diagram represents the 1,200 employees of a company, each a member of at least one of three clubs -- A, B and C. B-only = 500, A-C-only = 40, A-B-C (all three) = 20, B-C-only = 20. Total members of club A = 420, total members of club B = 590, total members of club C = 340.","setup_solution":"Let a,b,c be the only-regions, x=A-B only, y=A-C only, z=B-C only, w=all three. Using Total A=a+x+y+w=420, Total B=b+x+z+w=590, Total C=c+y+z+w=340, together with the sub-question conditions (C-only=260, A-union-C=700, exactly-two=110, A-and-B=70) solves uniquely to: A-only=310, B-only=500, C-only=260, A-B-only=50, A-C-only=40, B-C-only=20, all-three=20 (summing to 1,200, matching the total employees).","entity_count":3,"variables":1,"constraints":3,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8A_Q016","question_text":"How many employees are member of club C only?","options":{"A":"250","B":"240","C":"180","D":"260"},"correct_answer":"D","correct_answer_value":"260","solution_text":"C-only works out to 260 in the unique solution.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S16_20"},{"id":"LR_E8A_Q017","question_text":"How many employees are member of both club A and club B?","options":{"A":"50","B":"80","C":"70","D":"60"},"correct_answer":"C","correct_answer_value":"70","solution_text":"A-and-B (including those also in C) = A-B-only(50) + all-three(20) = 70.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S16_20"},{"id":"LR_E8A_Q018","question_text":"How many employees are not member of club B?","options":{"A":"340","B":"610","C":"630","D":"290"},"correct_answer":"B","correct_answer_value":"610","solution_text":"Not-B = Total employees - Total B = 1200 - 590 = 610.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S16_20"},{"id":"LR_E8A_Q019","question_text":"How many employees are member of club A or club C?","options":{"A":"850","B":"700","C":"975","D":"675"},"correct_answer":"B","correct_answer_value":"700","solution_text":"A-union-C = Total A + Total C - (A-C-only + all-three) = 420+340-(40+20) = 700.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S16_20"},{"id":"LR_E8A_Q020","question_text":"How many employees are member of exactly two clubs?","options":{"A":"110","B":"130","C":"98","D":"78"},"correct_answer":"A","correct_answer_value":"110","solution_text":"Exactly two = A-B-only(50) + A-C-only(40) + B-C-only(20) = 110.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S16_20"}],"question_image":"QIMG_LR_E8A_S16_20"},{"set_id":"LR_E8A_S21_25","exercise":"exercise_8a","type":"venn_diagrams","is_set":true,"setup_text":"P represents students who have a Voter ID card, Q represents students who have a Passport, R represents students who have a PAN card, and n represents students with none of the three (n=20). The diagram shows P-only=x, P-Q-only=12, Q-only=y, all-three=15, P-R-only=13, Q-R-only=14, R-only=z. Total students with a PAN card, R=100.","setup_solution":"R-only(z) is fixed by Total R=100: z+13+14+15=100, so z=58. This value stays constant across all sub-questions; x and y vary depending on each question's added hypothesis.","entity_count":3,"variables":2,"constraints":2,"case_splits":1,"resolution_type":"multiple","information_load":"high","solving_methodologies":["set_arithmetic","hypothetical_reasoning"],"questions":[{"id":"LR_E8A_Q021","question_text":"If the number of students who have Voter ID card is same as that of those who have Passport which in turn is same as PAN card, then how many students have at least one of the three ID proofs?","options":{"A":"260","B":"279","C":"250","D":"231"},"correct_answer":"D","correct_answer_value":"231","solution_text":"Setting Total P = Total Q = Total R = 100 gives x=60 (from x+12+13+15=100) and y=59 (from y+12+14+15=100). Total population = x+y+z+12+13+14+15+n = 60+59+58+12+13+14+15+20 = 251; at least one = 251-20 = 231.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150,"question_image":"QIMG_LR_E8A_S21_25"},{"id":"LR_E8A_Q022","question_text":"If the number of students who have voter ID card is half of the number of students who have PAN card then, how many students have only voter ID card?","options":{"A":"10","B":"20","C":"15","D":"Cannot be determined"},"correct_answer":"A","correct_answer_value":"10","solution_text":"Total P = 100/2 = 50. Since Total P = x+12+13+15 = x+40, x = 50-40 = 10.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S21_25"},{"id":"LR_E8A_Q023","question_text":"How many students have neither voter ID card nor Passport?","options":{"A":"64","B":"50","C":"78","D":"72"},"correct_answer":"C","correct_answer_value":"78","solution_text":"Neither P nor Q = R-only(58) + none(20) = 78.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S21_25"},{"id":"LR_E8A_Q024","question_text":"If x/y = 2/1 and y/z = 1/2 then how many students have only voter ID card?","options":{"A":"60","B":"58","C":"29","D":"18"},"correct_answer":"B","correct_answer_value":"58","solution_text":"With z=58 fixed, y/z=1/2 gives y=29, and x/y=2/1 gives x=58.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S21_25"},{"id":"LR_E8A_Q025","question_text":"If x = y = z then how many students do not have PAN card?","options":{"A":"120","B":"138","C":"160","D":"None of these"},"correct_answer":"D","correct_answer_value":"None of these","solution_text":"With x=y=z=58, students without PAN card = x+y+12+n = 58+58+12+20 = 148, which matches none of options A-C, so the answer is 'None of these'.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150,"question_image":"QIMG_LR_E8A_S21_25"}],"question_image":"QIMG_LR_E8A_S21_25"},{"set_id":"LR_E8A_S26_30","exercise":"exercise_8a","type":"venn_diagrams","is_set":true,"setup_text":"The Venn diagram shows three overlapping groups -- Entrepreneurs, Professors and Engineers -- with two numbers in each region: the top number is the count of males and the bottom number the count of females in that region.","setup_solution":"The male and female counts in each of the seven regions are read directly from the diagram; the sub-questions below combine specific regions (by gender, by category overlap, or both) according to the provided answer key.","entity_count":3,"variables":2,"constraints":3,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["diagram_region_reading","set_arithmetic"],"questions":[{"id":"LR_E8A_Q026","question_text":"How many female Entrepreneurs are Professors also?","options":{"A":"20","B":"23","C":"47","D":"43"},"correct_answer":"D","correct_answer_value":"43","solution_text":"Summing the female counts in the regions where Entrepreneurs and Professors overlap (including the all-three region) gives 43.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S26_30"},{"id":"LR_E8A_Q027","question_text":"How many Professors are neither Entrepreneurs nor Engineers?","options":{"A":"20","B":"28","C":"30","D":"38"},"correct_answer":"C","correct_answer_value":"30","solution_text":"Summing the male and female counts in the Professors-only region gives 30.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8A_S26_30"},{"id":"LR_E8A_Q028","question_text":"How many male Professors are not Entrepreneurs?","options":{"A":"29","B":"31","C":"49","D":"58"},"correct_answer":"B","correct_answer_value":"31","solution_text":"Summing the male counts across the Professors regions that exclude Entrepreneurs gives 31.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S26_30"},{"id":"LR_E8A_Q029","question_text":"How many females are not Engineers?","options":{"A":"51","B":"48","C":"58","D":"60"},"correct_answer":"A","correct_answer_value":"51","solution_text":"Summing the female counts across all regions outside the Engineers circle gives 51.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S26_30"},{"id":"LR_E8A_Q030","question_text":"How many Professors are also Entrepreneurs as well as Engineers?","options":{"A":"37","B":"40","C":"48","D":"51"},"correct_answer":"A","correct_answer_value":"37","solution_text":"Summing the male and female counts in the all-three (Entrepreneurs-Professors-Engineers) region gives 37.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8A_S26_30"}],"question_image":"QIMG_LR_E8A_S26_30"},{"set_id":"LR_E8B_S1_5","exercise":"exercise_8b","type":"venn_diagrams","is_set":true,"setup_text":"In a class of 150 students, 45 take History, 65 take Geography and 10 take both History and Geography.","setup_solution":"Union (History or Geography) = 45+65-10 = 100. Only Geography = 65-10=55. Only History = 45-10=35. Not taking either = 150-100=50.","type_specific":{"note":"Question 3's options (10, 35, 100, 140) do not include 50, the value obtained from the stated total of 150 students (150-100=50) -- the same computation that correctly answers Question 5 (also 'do not take either/any' phrased differently) with option C=50. The provided answer key marks Q3 as D (140), which is not derivable from the stated total of 150 and appears to be a source error (possibly Q3 was intended to use a different total, e.g. 240, or its options were meant to include 50). Transcribed as printed and keyed, per instruction not to alter source content."},"entity_count":2,"variables":1,"constraints":3,"case_splits":1,"resolution_type":"single","information_load":"low","solving_methodologies":["set_arithmetic"],"questions":[{"id":"LR_E8B_Q001","question_text":"How many students take only Geography?","options":{"A":"45","B":"10","C":"55","D":"65"},"correct_answer":"C","correct_answer_value":"55","solution_text":"Only Geography = 65 - 10 = 55.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"easy","time_benchmark_seconds":60},{"id":"LR_E8B_Q002","question_text":"How many take only History?","options":{"A":"65","B":"35","C":"10","D":"45"},"correct_answer":"B","correct_answer_value":"35","solution_text":"Only History = 45 - 10 = 35.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"easy","time_benchmark_seconds":60},{"id":"LR_E8B_Q003","question_text":"How many do not take either History or Geography?","options":{"A":"10","B":"35","C":"100","D":"140"},"correct_answer":"D","correct_answer_value":"140","solution_text":"Per the provided answer key. Note: using the stated total of 150 students and the union of 100 (History or Geography), the arithmetic gives 150-100=50, which is not among this question's listed options -- see the type_specific note on this set for the discrepancy.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"easy","time_benchmark_seconds":60},{"id":"LR_E8B_Q004","question_text":"How many students take at least one subject?","options":{"A":"10","B":"90","C":"50","D":"100"},"correct_answer":"D","correct_answer_value":"100","solution_text":"At least one = 45+65-10 = 100.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"easy","time_benchmark_seconds":60},{"id":"LR_E8B_Q005","question_text":"How many students do not take any of the two subjects?","options":{"A":"90","B":"10","C":"50","D":"100"},"correct_answer":"C","correct_answer_value":"50","solution_text":"Not taking either = 150 - 100 = 50.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"easy","time_benchmark_seconds":60}]},{"set_id":"LR_E8B_S6_10","exercise":"exercise_8b","type":"venn_diagrams","is_set":true,"setup_text":"In a survey among 200 mobile phone using families: 140 use Panasonic, 120 use Nokia, 143 use Siemens, 95 use both Panasonic and Nokia, 85 use both Nokia and Siemens, 93 use both Panasonic and Siemens, 70 families use phones of all three companies.","setup_solution":"Only-Panasonic = 140-95-93+70=22. Only-Nokia = 120-95-85+70=10. Only-Siemens = 143-93-85+70=35. Panasonic-Nokia-only (not Siemens) = 95-70=25. Nokia-Siemens-only = 85-70=15. Panasonic-Siemens-only = 93-70=23. Union (at least one company) = 140+120+143-95-85-93+70=200, which equals the total of 200 families, so every family uses at least one company's phone.","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic"],"questions":[{"id":"LR_E8B_Q006","question_text":"How many families use mobilephones of only Siemens?","options":{"A":"50","B":"35","C":"70","D":"143"},"correct_answer":"B","correct_answer_value":"35","solution_text":"Only-Siemens = 143-93-85+70 = 35.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q007","question_text":"How many families use mobilephones of both Panasonic and Nokia but not Siemens?","options":{"A":"25","B":"57","C":"165","D":"95"},"correct_answer":"A","correct_answer_value":"25","solution_text":"Panasonic-Nokia-only = 95-70 = 25.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q008","question_text":"How many families use mobilephones of exactly one Company?","options":{"A":"63","B":"67","C":"70","D":"200"},"correct_answer":"B","correct_answer_value":"67","solution_text":"Exactly one = only-Panasonic(22)+only-Nokia(10)+only-Siemens(35) = 67.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q009","question_text":"How many families use neither Panasonic nor Siemens?","options":{"A":"40","B":"120","C":"110","D":"10"},"correct_answer":"D","correct_answer_value":"10","solution_text":"Neither Panasonic nor Siemens = 200-(140+143-93) = 200-190 = 10.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q010","question_text":"How many families use none of the mobilephones?","options":{"A":"10","B":"70","C":"0","D":"Cannot be determined"},"correct_answer":"C","correct_answer_value":"0","solution_text":"The union of all three companies equals the full 200 families, so none = 200-200 = 0.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E8B_S11_15","exercise":"exercise_8b","type":"venn_diagrams","is_set":true,"setup_text":"A survey was conducted among 100 students in a class who read detective novels written by Conan Doyle or Agatha Christie or both. Due to a recording error most figures were missing from a table with columns Doyle, Christie, Both, Total and rows Male, Female, Total. Given cells: Female-Doyle=40, column Total-Christie=70, grand Total=100. Additional information: (A) 37% of the students read both Doyle and Christie; (B) the ratio of males to females is 1:1; (C) 50% of the females read books of both the authors.","setup_solution":"Grand total=100 with a 1:1 male:female ratio gives Male total=Female total=50. Both(total)=37% of 100=37; Female-Both=50% of 50=25, so Male-Both=37-25=12. Female-Doyle=40 (given), so Female-Christie = Female total - Female-Doyle + Female-Both = 50-40+25=35. Column Total-Christie=70 gives Male-Christie=70-35=35. Male total=50=Male-Doyle+Male-Christie-Male-Both=Male-Doyle+35-12, so Male-Doyle=27. Check: Doyle total=27+40=67, Christie total=35+35=70 (matches given), Both=37, Union=67+70-37=100 (matches grand total).","entity_count":2,"variables":2,"constraints":3,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8B_Q011","question_text":"How many males read books by both the authors?","options":{"A":"10","B":"12","C":"37","D":"45"},"correct_answer":"B","correct_answer_value":"12","solution_text":"Male-Both = 37 (total both) - 25 (female both) = 12.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8B_S11_15"},{"id":"LR_E8B_Q012","question_text":"How many students read books by only Christie?","options":{"A":"70","B":"10","C":"33","D":"23"},"correct_answer":"C","correct_answer_value":"33","solution_text":"Only Christie = Christie total(70) - Both(37) = 33.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8B_S11_15"},{"id":"LR_E8B_Q013","question_text":"How many females read books by only Doyle?","options":{"A":"25","B":"40","C":"35","D":"15"},"correct_answer":"D","correct_answer_value":"15","solution_text":"Only-Doyle females = Female-Doyle(40) - Female-Both(25) = 15.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8B_S11_15"},{"id":"LR_E8B_Q014","question_text":"How many students do not read books by both the authors?","options":{"A":"12","B":"27","C":"37","D":"63"},"correct_answer":"D","correct_answer_value":"63","solution_text":"Not-both = grand total(100) - Both(37) = 63.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8B_S11_15"},{"id":"LR_E8B_Q015","question_text":"How many males read books by Doyle?","options":{"A":"27","B":"67","C":"12","D":"15"},"correct_answer":"A","correct_answer_value":"27","solution_text":"Male-Doyle = 27, from the derived table.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8B_S11_15"}],"question_image":"QIMG_LR_E8B_S11_15"},{"set_id":"LR_E8B_S16_20","exercise":"exercise_8b","type":"venn_diagrams","is_set":true,"setup_text":"At a marriage party, ice creams of three flavours -- Vanilla, Strawberry and Chocolate -- are served. 100 guests ate Vanilla, 150 ate Strawberry, 170 ate Chocolate, 50 ate Vanilla and Strawberry, 60 ate Chocolate and Strawberry, 30 ate Vanilla and Chocolate, 20 ate all three flavours, and 80 guests ate none.","setup_solution":"Union of the three flavours = 100+150+170-50-60-30+20=300. Total guests = union + none = 300+80=380. Vanilla-Strawberry-only=50-20=30, Chocolate-Strawberry-only=60-20=40, Vanilla-Chocolate-only=30-20=10; at least two = 30+40+10+20=100.","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic"],"questions":[{"id":"LR_E8B_Q016","question_text":"How many guests have attended the party?","options":{"A":"250","B":"280","C":"400","D":"380"},"correct_answer":"D","correct_answer_value":"380","solution_text":"Total = union(300) + none(80) = 380.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q017","question_text":"How many guests have eaten the ice creams of at least two flavours?","options":{"A":"190","B":"100","C":"150","D":"180"},"correct_answer":"B","correct_answer_value":"100","solution_text":"At least two = (30)+(40)+(10)+20(all three) = 100.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q018","question_text":"How many guests have eaten the ice creams of Vanilla and Strawberry flavours only?","options":{"A":"20","B":"30","C":"40","D":"10"},"correct_answer":"B","correct_answer_value":"30","solution_text":"Vanilla-Strawberry-only = 50-20 = 30.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q019","question_text":"How many guests have eaten Vanilla ice cream and Chocolate ice cream but not Strawberry ice cream?","options":{"A":"40","B":"30","C":"10","D":"20"},"correct_answer":"C","correct_answer_value":"10","solution_text":"Vanilla-Chocolate-only = 30-20 = 10.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q020","question_text":"How many guests have not eaten the Vanilla ice cream?","options":{"A":"170","B":"150","C":"250","D":"280"},"correct_answer":"D","correct_answer_value":"280","solution_text":"Not-Vanilla = Total(380) - Vanilla(100) = 280.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E8B_S21_25","exercise":"exercise_8b","type":"venn_diagrams","is_set":true,"setup_text":"In a locality, three magazines are read: India Today, Sports Star and Business India. 45 people read only one magazine, 20 read exactly two magazines, 5 read all three. There is no one who does not read any of the three magazines.","setup_solution":"Total population = only-one(45) + exactly-two(20) + all-three(5) = 70.","entity_count":3,"variables":1,"constraints":3,"case_splits":1,"resolution_type":"multiple","information_load":"medium","solving_methodologies":["set_arithmetic","hypothetical_reasoning"],"questions":[{"id":"LR_E8B_Q021","question_text":"How many people are there in the locality?","options":{"A":"65","B":"70","C":"50","D":"90"},"correct_answer":"B","correct_answer_value":"70","solution_text":"Total = 45+20+5 = 70.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75},{"id":"LR_E8B_Q022","question_text":"How many people read at least two magazines?","options":{"A":"25","B":"20","C":"50","D":"45"},"correct_answer":"A","correct_answer_value":"25","solution_text":"At least two = exactly-two(20) + all-three(5) = 25.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75},{"id":"LR_E8B_Q023","question_text":"If the ratio of people who read India Today is to those who read Sports Star is to those who read Business India is 2:3:4 and 18 people read India Today, then how many read Sports Star?","options":{"A":"28","B":"31","C":"27","D":"54"},"correct_answer":"C","correct_answer_value":"27","solution_text":"India Today (2 parts) = 18, so 1 part = 9. Sports Star (3 parts) = 27.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q024","question_text":"If 10 people stop reading India Today and start reading Business India, then what is the maximum number of people who read exactly two magazines?","options":{"A":"20","B":"30","C":"25","D":"55"},"correct_answer":"A","correct_answer_value":"20","solution_text":"The 10 switching readers must currently read India Today without Business India, so they come from either the 'only India Today' group or the 'India Today + Sports Star only' group. Either way, swapping India Today for Business India keeps their magazine-count the same (still reading exactly one, or still reading exactly two), so the exactly-two count is unchanged at 20 regardless of which sub-group switches.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8B_Q025","question_text":"What percentage of the people who read at least one magazine read exactly two magazines?","options":{"A":"25%","B":"20%","C":"28 4/7%","D":"None of these"},"correct_answer":"C","correct_answer_value":"28 4/7%","solution_text":"Percentage = 20/70 x 100 = 2/7 x 100 = 28 4/7%.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E8B_S26_30","exercise":"exercise_8b","type":"venn_diagrams","is_set":true,"setup_text":"In a music centre 'Sangeet Mahal', cassettes belong to various types of music: 125 cassettes were Pop Music, 135 were Classical Music, 95 were Light Music. 60 cassettes had a mixture of at least two of the music types, and 10 cassettes had a mixture of all three. Every cassette contained at least one of the above mentioned types of music.","setup_solution":"Exactly-two = (at least two, 60) - (all three, 10) = 50. Sum of pairwise totals (Pop-Classical + Classical-Light + Pop-Light, each including the all-three cassettes) = exactly-two(50) + 3x all-three(10)... more directly: Total = Pop+Classical+Light - (sum of pairwise totals) + all-three, and since (at least two)=sum of pairwise totals - 2x(all-three), sum of pairwise totals = 60+2(10)=80. Total = 125+135+95-80+10 = 285, matching the fact that every cassette has at least one type. Exactly-one = 285-50-10 = 225.","entity_count":3,"variables":1,"constraints":3,"case_splits":1,"resolution_type":"multiple","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8B_Q026","question_text":"How many cassettes were of exactly one type of music?","options":{"A":"60","B":"70","C":"225","D":"200"},"correct_answer":"C","correct_answer_value":"225","solution_text":"Exactly-one = Total(285) - exactly-two(50) - all-three(10) = 225.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120},{"id":"LR_E8B_Q027","question_text":"How many cassettes were of exactly two types of music?","options":{"A":"60","B":"50","C":"100","D":"90"},"correct_answer":"B","correct_answer_value":"50","solution_text":"Exactly-two = at least-two(60) - all-three(10) = 50.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q028","question_text":"How many cassettes had music of at least one type?","options":{"A":"285","B":"225","C":"90","D":"205"},"correct_answer":"A","correct_answer_value":"285","solution_text":"Every cassette has at least one type, so this equals the grand total, 285.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8B_Q029","question_text":"If the number of cassettes of only Pop Music is equal to that of only Light Music, which is twice the number of cassettes of only Classical Music type, then how many cassettes of only Classical Music were there?","options":{"A":"225","B":"75","C":"90","D":"45"},"correct_answer":"D","correct_answer_value":"45","solution_text":"Let only-Classical=y; only-Pop=only-Light=2y. Sum of only-categories is fixed at 225 (from Q26), so 2y+y+2y=5y=225, giving y=45.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8B_Q030","question_text":"If the number of cassettes of only Pop Music is equal to 75 and the number of cassettes of both Pop and Classical but not Light is equal to the number of cassettes of both Pop and Light but not Classical, then how many cassettes are there in the Music Centre which are both Classical and Light but not Pop?","options":{"A":"0","B":"20","C":"50","D":"10"},"correct_answer":"D","correct_answer_value":"10","solution_text":"With only-Pop=75, Pop's total(125)=75+(Pop-Classical-only)+(Pop-Light-only)+10(all three). Setting Pop-Classical-only=Pop-Light-only=a gives 125=85+2a, so a=20. Since exactly-two totals 50, Classical-Light-only = 50-2(20) = 10.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150}]},{"set_id":"LR_E8C_S1_3","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"In a class of 100 students, 50 students passed in Mathematics and 70 passed in English. 5 students failed in both Mathematics and English.","setup_solution":"Passed at least one = 100-5=95. Passed both = 50+70-95=25.","entity_count":2,"variables":1,"constraints":3,"case_splits":1,"resolution_type":"single","information_load":"low","solving_methodologies":["set_arithmetic"],"questions":[{"id":"LR_E8C_Q001","question_text":"How many students passed in both the subjects?","options":{"A":"25","B":"50","C":"70","D":"5"},"correct_answer":"A","correct_answer_value":"25","solution_text":"Passed both = 50+70-95(passed at least one) = 25.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"easy","time_benchmark_seconds":60},{"id":"LR_E8C_Q002","question_text":"How many students passed in exactly one of the two subjects?","options":{"A":"5","B":"15","C":"95","D":"70"},"correct_answer":"D","correct_answer_value":"70","solution_text":"Exactly one = passed at least one(95) - passed both(25) = 70.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"easy","time_benchmark_seconds":60},{"id":"LR_E8C_Q003","question_text":"How many students failed in at least one subject?","options":{"A":"95","B":"50","C":"75","D":"70"},"correct_answer":"C","correct_answer_value":"75","solution_text":"Failed at least one = Total - passed both = 100-25 = 75.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"easy","time_benchmark_seconds":60}]},{"set_id":"LR_E8C_S4_6","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"In a class, 30% of the students gave their names to participate in the NSS and 75% to participate in the NCC. Three students participate in neither of these two and six students wanted to participate in both.","setup_solution":"Let N=class size. Union = N-3 (neither). Union also = 0.3N+0.75N-6 = 1.05N-6. Equating: N-3=1.05N-6, giving 0.05N=3, N=60.","entity_count":2,"variables":1,"constraints":3,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8C_Q004","question_text":"How many students are there in the class?","options":{"A":"100","B":"75","C":"60","D":"80"},"correct_answer":"C","correct_answer_value":"60","solution_text":"Solving N-3=1.05N-6 gives N=60.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8C_Q005","question_text":"What percentage of students wants to participate in only one programme -- either NSS or NCC?","options":{"A":"85%","B":"90%","C":"75%","D":"20%"},"correct_answer":"A","correct_answer_value":"85%","solution_text":"Only one = Union(57) - both(6) = 51. Percentage = 51/60 x 100 = 85%.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8C_Q006","question_text":"How many students want to participate in at least one programme?","options":{"A":"97","B":"87","C":"147","D":"57"},"correct_answer":"D","correct_answer_value":"57","solution_text":"At least one = N - neither = 60-3 = 57.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75}]},{"set_id":"LR_E8C_S7_9","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"In a locality, 60% of people read the newspaper Times of India and 35% read only the newspaper The Hindu. 10% read both the newspapers and 240 people do not read any of the two newspapers.","setup_solution":"Let N=total. Only-TOI = 0.6N-0.1N=0.5N. Union = 0.5N+0.35N+0.1N=0.95N. None = N-0.95N=0.05N=240, giving N=4800.","entity_count":2,"variables":1,"constraints":3,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8C_Q007","question_text":"How many people are there in that locality?","options":{"A":"4800","B":"2400","C":"2000","D":"4000"},"correct_answer":"A","correct_answer_value":"4800","solution_text":"0.05N=240 gives N=4800.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8C_Q008","question_text":"How many people read only Times of India?","options":{"A":"2880","B":"2000","C":"2400","D":"2800"},"correct_answer":"C","correct_answer_value":"2400","solution_text":"Only-TOI = 0.5 x 4800 = 2400.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75},{"id":"LR_E8C_Q009","question_text":"How many people read at most one of the two newspapers?","options":{"A":"4200","B":"4400","C":"4560","D":"4320"},"correct_answer":"D","correct_answer_value":"4320","solution_text":"At most one = Total - both = 4800-480 = 4320.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E8C_S10_12","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"In an institute, 150 students are members of 'Club A', 140 students are members of 'Club B' and 165 students are members of 'Club C'. 25 students are members of both Clubs A and B, 35 students are members of both Clubs B and C, and 30 students are members of clubs A and C. 15 students are members of all the three Clubs. Each student is a member of at least one of the Clubs.","setup_solution":"AB-only=25-15=10, BC-only=35-15=20, AC-only=30-15=15. Only-A=150-25-30+15=110, Only-B=140-25-35+15=95, Only-C=165-35-30+15=115. Total = 110+95+115+10+20+15+15=380.","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic"],"questions":[{"id":"LR_E8C_Q010","question_text":"How many students are not members of Club C?","options":{"A":"215","B":"200","C":"210","D":"310"},"correct_answer":"A","correct_answer_value":"215","solution_text":"Not-C = Total(380) - Club C total(165) = 215.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8C_Q011","question_text":"How many students are members of both the Clubs A and B but not C?","options":{"A":"10","B":"20","C":"15","D":"30"},"correct_answer":"A","correct_answer_value":"10","solution_text":"AB-only = 25-15 = 10.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":75},{"id":"LR_E8C_Q012","question_text":"How many students are the members of Club A or Club C?","options":{"A":"310","B":"320","C":"325","D":"285"},"correct_answer":"D","correct_answer_value":"285","solution_text":"A-union-C = 150+165-30 = 285.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E8C_S13_16","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"A survey was conducted among 600 bicycle owners. 200 people had Hero Ranger, 250 people had BSA SLR and 300 people had Atlas MTB bicycles. Seventy of them had exactly 2 of the 3 brands of bicycles. Each owns at least one of the three brands.","setup_solution":"Using Total=H+B+A-(sum of pairwise totals)+T=600 together with exactly-two(sum of pairwise totals-3T)=70 gives 680-2T=600, so T(all three)=40.","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"multiple","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8C_Q013","question_text":"How many people had all the three brands?","options":{"A":"70","B":"40","C":"60","D":"110"},"correct_answer":"B","correct_answer_value":"40","solution_text":"All three = 40, from solving 680-2T=600.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120},{"id":"LR_E8C_Q014","question_text":"If 16 owners had only BSA SLR and Atlas MTB with them, then how many people have only Hero Ranger with them?","options":{"A":"54","B":"72","C":"98","D":"106"},"correct_answer":"D","correct_answer_value":"106","solution_text":"With BSA-Atlas-only=16 and exactly-two total=70, the other two exactly-two components sum to 54. Only-Hero = 200 - (Hero-BSA total) - (Hero-Atlas total) + 40 = 200-54-40 = 106.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8C_Q015","question_text":"If 160 people had only BSA SLR cycles, then how many have only Atlas MTB and Hero Ranger with them?","options":{"A":"10","B":"20","C":"30","D":"50"},"correct_answer":"B","correct_answer_value":"20","solution_text":"Only-BSA=160 gives (Hero-BSA-only + BSA-Atlas-only)=250-160-40=50. Since exactly-two totals 70, Hero-Atlas-only = 70-50=20.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8C_Q016","question_text":"How many owners have only one brand of cycle with them?","options":{"A":"70","B":"200","C":"490","D":"250"},"correct_answer":"C","correct_answer_value":"490","solution_text":"Exactly-one = Total(600) - exactly-two(70) - all-three(40) = 490.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E8C_S17_20","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"A group of people who read the three magazines -- Business World (BW), Business Today (BT) and Business Standards (BS) -- is surveyed. 49% of the people read BW, 49% read BT and 52% read BS. 10% of the people read all the three. 26% read both BW and BS, 14% read both BS and BT, 15% read both BT and BW.","setup_solution":"From Q17 (people not reading BT = 102 = 51% of total), the total is N=200, giving BW=BT=98, BS=104, all-three=20. With BW-BS(26%)=52 as the total BW-and-BS overlap (including the all-three group), Q19/Q20's at-least-two total of 100 only reconciles if the BW-BT overlap is 30% (=60) rather than the 15% as printed -- likely a printer misread of '30%' as '15%' -- giving BS-BT(14%)=28. With these three pairwise totals (52, 60, 28) and all-three=20: BW-BS-only=32, BW-BT-only=40, BS-BT-only=8, only-BW=6, only-BT=30, only-BS=44, and none=20.","type_specific":{"note":"The setup_text above is transcribed exactly as printed ('15% read both BT and BW'), per instruction not to alter source content. However, that figure is inconsistent with the given answers to Q19 and Q20 (people reading at least/at most two magazines) -- solving with the printed 15% gives 110 people reading at least two, not the keyed 100. Reconciling against the answer key across Q17-20 simultaneously points to 30% (not 15%) as the value that makes every sub-answer consistent; the setup_solution and all four questions' solution_text use that reconciled figure."},"entity_count":3,"variables":1,"constraints":6,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8C_Q017","question_text":"How many people do not read BT?","options":{"A":"64","B":"102","C":"92","D":"108"},"correct_answer":"B","correct_answer_value":"102","solution_text":"Not-BT = Total - BT = 51% of N. Setting this to 102 pins the total population at N=200.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8C_Q018","question_text":"Among the people who read BW, how many people do not read BS?","options":{"A":"102","B":"46","C":"84","D":"59"},"correct_answer":"B","correct_answer_value":"46","solution_text":"BW-not-BS = BW total(98) - BW-and-BS total(52) = 46.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8C_Q019","question_text":"How many people read at least two magazines?","options":{"A":"64","B":"109","C":"100","D":"129"},"correct_answer":"C","correct_answer_value":"100","solution_text":"At least two = (sum of the three pairwise totals, 52+60+28=140) - 2x(all three, 20) = 100.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120},{"id":"LR_E8C_Q020","question_text":"How many people read at most one magazine?","options":{"A":"100","B":"120","C":"105","D":"109"},"correct_answer":"A","correct_answer_value":"100","solution_text":"At most one = Total(200) - at least two(100) = 100.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120}]},{"set_id":"LR_E8C_S21_23","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"Out of a group of 315 students who went to Mumbai, 125 visited Essel World, 140 visited Lumbini Garden and 160 visited Film Nagar. Twenty five of them visited all the three places while 200 visited exactly one of the three places. The number of students who visited exactly 2 out of the three places is five times as many as those who have not visited any of the places.","setup_solution":"Let k=visited none. Exactly-two=5k. Total: 200+5k+25+k=315, giving 6k=90, k=15. So none=15 and exactly-two=75.","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"multiple","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8C_Q021","question_text":"How many students visited not more than one place?","options":{"A":"200","B":"180","C":"250","D":"215"},"correct_answer":"D","correct_answer_value":"215","solution_text":"Not more than one = exactly-one(200) + none(15) = 215.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8C_Q022","question_text":"If the number of students who visited at least one of the two places, Lumbini Gardens and Film Nagar, is 255, then how many students visited only Essel World?","options":{"A":"45","B":"25","C":"125","D":"75"},"correct_answer":"A","correct_answer_value":"45","solution_text":"Lumbini-Film Nagar total = 140+160-(Lumbini-FilmNagar overlap)=255 gives that overlap=45, so Lumbini-FilmNagar-only=45-25(all three)=20. Working through Essel World's total (125=onlyEssel+EL-only+EF-only+25) together with the exactly-two total (75) and the Lumbini/Film Nagar totals gives only-Essel World=45.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E8C_Q023","question_text":"If the number of students who visited at least one of the two places, Lumbini Gardens and Film Nagar, is 255, then how many students visited only one of the two places, Lumbini Gardens and Film Nagar (and not any of the other two places)?","options":{"A":"215","B":"125","C":"155","D":"175"},"correct_answer":"C","correct_answer_value":"155","solution_text":"Only-Lumbini + only-Film Nagar = exactly-one total(200) - only-Essel World(45) = 155.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150}]},{"set_id":"LR_E8C_S24_27","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"The following table represents a survey conducted in five companies to find the number of Engineers and the number of employees who are from Delhi, as shown below.","setup_solution":"Neither-Engineer-nor-Delhi = Total-Engineer-Delhi+Both for each company: A=50, B=30, C=20, D=20, E=15.","entity_count":5,"variables":2,"constraints":4,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic"],"questions":[{"id":"LR_E8C_Q024","question_text":"Which company has the least number of employees who are neither Engineers nor from Delhi?","options":{"A":"Company C","B":"Company D","C":"Company E","D":"Company B"},"correct_answer":"C","correct_answer_value":"Company E","solution_text":"Company E has the least such employees, 15, versus A=50, B=30, C=20, D=20.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8C_S24_27"},{"id":"LR_E8C_Q025","question_text":"How many employees of company C are Engineers, but are not from Delhi?","options":{"A":"10","B":"20","C":"15","D":"None of these"},"correct_answer":"D","correct_answer_value":"None of these","solution_text":"Engineer-not-Delhi for Company C = 130-130 = 0, which matches none of options A-C, so the answer is 'None of these'.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8C_S24_27"},{"id":"LR_E8C_Q026","question_text":"How many employees of company B are neither Engineers nor from Delhi?","options":{"A":"30","B":"20","C":"40","D":"50"},"correct_answer":"A","correct_answer_value":"30","solution_text":"Neither for Company B = 400-320-300+250 = 30.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8C_S24_27"},{"id":"LR_E8C_Q027","question_text":"How many employees of company D are either engineers or from Delhi?","options":{"A":"250","B":"230","C":"130","D":"90"},"correct_answer":"B","correct_answer_value":"230","solution_text":"Either for Company D = 220+140-130 = 230.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8C_S24_27"}],"question_image":"QIMG_LR_E8C_S24_27","wide_reference":true},{"set_id":"LR_E8C_S28_30","exercise":"exercise_8c","type":"venn_diagrams","is_set":true,"setup_text":"In a class of 160 students, 30 students passed only in English and 40 students passed only in Maths. 32 students passed in Science and Maths and 30 students passed in Science and English. 11 students passed in all the three subjects. Every student passed in atleast one of the three subjects.","setup_solution":"Science-Maths-only=32-11=21, Science-English-only=30-11=19. From the total: 160=30(onlyE)+40(onlyM)+onlyS+EM-only+21+19+11, giving onlyS+EM-only=39.","entity_count":3,"variables":1,"constraints":4,"case_splits":2,"resolution_type":"multiple","information_load":"high","solving_methodologies":["set_arithmetic","hypothetical_reasoning"],"questions":[{"id":"LR_E8C_Q028","question_text":"If the number of students who are passed in Maths is more than the number of students who are passed in Science, then what is the maximum possible number of students, who passed in only Science?","options":{"A":"29","B":"18","C":"31","D":"23"},"correct_answer":"A","correct_answer_value":"29","solution_text":"Maths>Science translates to onlyS<30 (using onlyS+EM-only=39 and the totals for Maths and Science). The maximum integer value satisfying this is 29.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8C_Q029","question_text":"If the number of students who passed in Science is more than the number of students who are passed in English, then what is the maximum possible number of students, who passed in English as well as in Maths?","options":{"A":"15","B":"27","C":"14","D":"25"},"correct_answer":"D","correct_answer_value":"25","solution_text":"Science>English translates to EM-only<15. The maximum integer EM-only=14, so English-and-Maths (including all three) = 14+11=25.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8C_Q030","question_text":"If the number of students passed in English is 68, then how many students passed in exactly one subject?","options":{"A":"101","B":"139","C":"140","D":"150"},"correct_answer":"A","correct_answer_value":"101","solution_text":"English total=68 gives EM-only=8, so onlyS=39-8=31. Exactly one = 30(onlyE)+40(onlyM)+31(onlyS) = 101.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150}]},{"set_id":"LR_E8D_S1_3","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"A table shows Business World (BW) and Business Today (BT) readers by age group and gender, split into BW-only, BT-only, Both, and Total-including-non-readers columns, as shown below.","setup_solution":"For each age/gender cell, 'read neither' = Total - (BW+BT-Both). Aggregating across age groups gives the readership breakdowns used in the three questions below.","entity_count":2,"variables":3,"constraints":12,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic"],"questions":[{"id":"LR_E8D_Q001","question_text":"How many males in 15-34 years age group do not read any of the 2 magazines?","options":{"A":"15","B":"45","C":"75","D":"25"},"correct_answer":"D","correct_answer_value":"25","solution_text":"Neither = Total-M(265) - (BW-M(175)+BT-M(105)-Both-M(40)) = 265-240 = 25.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8D_S1_3"},{"id":"LR_E8D_Q002","question_text":"Approximately, what percentage of the BT readers, are above 15 years of age?","options":{"A":"75%","B":"45%","C":"65%","D":"80%"},"correct_answer":"C","correct_answer_value":"65%","solution_text":"Total BT readers = (155+65)+(105+85)+(120+100) = 630. Above 15 = 190+220 = 410. 410/630 x 100 ~= 65%.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8D_S1_3"},{"id":"LR_E8D_Q003","question_text":"What percentage of females, who read neither BT nor BW, are below 15 years of age?","options":{"A":"30%","B":"60%","C":"40%","D":"20%"},"correct_answer":"A","correct_answer_value":"30%","solution_text":"Neither-females per age group: <15: 115-100=15; 15-34: 190-160=30; >=35: 195-190=5. Total=50. Below-15 fraction = 15/50 = 30%.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":120,"question_image":"QIMG_LR_E8D_S1_3"}],"question_image":"QIMG_LR_E8D_S1_3","wide_reference":true},{"set_id":"LR_E8D_S4_7","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"All 1000 students at a summer camp are engaged in at least two of five activities -- Painting, Swimming, Dancing, Singing or Karate. The number of students engaged in every combination of exactly two activities is three times the number engaged in every combination of exactly three activities. The number of students engaged in all five activities is a third of that engaged in exactly four activities. The number of students engaged in every combination of exactly four activities is the same.","setup_solution":"Let T2,T3,T4,T5 be the aggregate totals for exactly-two, exactly-three, exactly-four and all-five. T2=3xT3 and T4=3xT5 (from the given ratios), and T2+T3+T4+T5=1000 gives 4xT3+4xT5=1000, i.e. T3+T5=250. This relation, together with each question's added information, pins down the specific values.","entity_count":5,"variables":1,"constraints":4,"case_splits":2,"resolution_type":"multiple","information_load":"high","solving_methodologies":["algebraic_deduction","combinatorial_counting"],"questions":[{"id":"LR_E8D_Q004","question_text":"If the number of students enrolled in all the five activities is 100, then the number of students engaged in only painting and karate is","options":{"A":"150","B":"45","C":"450","D":"Cannot be determined"},"correct_answer":"B","correct_answer_value":"45","solution_text":"T5=100 gives T4(aggregate)=3x100=300, so per-combo E4=300/5=60. From T3+T5=250, T3=150, so per-combo E3=150/10=15. Per-combo E2=3xE3=45 -- the value for any specific pair, including painting and karate.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E8D_Q005","question_text":"If the number of students engaged in exactly three activities is 1.5 times the number of students engaged in all the five activities, then which of the following is true?","options":{"A":"The number of students engaged in only swimming, dancing and painting is 15.","B":"The number of students engaged in all the five activities is 100.","C":"Both (A) and (B)","D":"Neither (A) nor (B)"},"correct_answer":"C","correct_answer_value":"Both (A) and (B)","solution_text":"Reading 'exactly three activities' as the aggregate T3=1.5xT5, and using T3+T5=250 with 40x(T3/10)+4T5=1000 (i.e. 4T3+4T5=1000), solving gives T5=100 and T3=150, so per-combo E3=15 -- matching both (A) and (B).","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E8D_Q006","question_text":"If the number of students enrolled in painting, swimming, dancing, singing and karate are 750, 800, 400, 900 and 600 respectively, then which of the following is definitely false?","options":{"A":"The number of students engaged in only painting, dancing, singing and karate is 90.","B":"The number of students engaged in exactly two activities is 300.","C":"The number of students engaged in exactly three activities is lesser than that engaged in only dancing, singing, swimming and karate.","D":"The number of students engaged in all the five activities is 150."},"correct_answer":"C","correct_answer_value":"The number of students engaged in exactly three activities is lesser than that engaged in only dancing, singing, swimming and karate.","solution_text":"Using the sum of enrollments (3450) with 2T2+3T3+4T4+5T5=3450, T2=3T3, T4=3T5 and T2+T3+T4+T5=1000, solving gives T5=150, T4=450 (so per-combo E4=90, matching A), T3=100, T2=300 (matching B and D). Option C compares the aggregate T3(100) to a single exactly-four combo (90) and claims T3 is smaller, but 100 is not less than 90, so C is definitely false.","question_operation":"statement_verification","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E8D_Q007","question_text":"In the previous question, if the number of students engaged in painting is not known, then which of the following can be that value?","options":{"A":"270","B":"90","C":"360","D":"120"},"correct_answer":"A","correct_answer_value":"270","solution_text":"With the other four enrollments fixed (800,400,900,600) and using T3+T5=250 together with the sum-of-enrollments equation, T5=(Painting+450)/8 must be a non-negative integer. Only Painting=270 gives an integer T5(=90); the other options do not.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180}]},{"set_id":"LR_E8D_S8_10","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"Out of a group of 245 pilgrims, 105 visited Badrinath, 95 visited Kedarnath and 95 visited Somnath. Fifteen of them visited all three shrines, while 190 visited exactly one of the three shrines. The number of pilgrims who visited exactly two out of the three shrines is three times as many as those who have not visited any one of the three shrines.","setup_solution":"Let k=visited none, exactly-two=3k. 190+3k+15+k=245 gives 4k=40, k=10. So none=10 and exactly-two=30.","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"multiple","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8D_Q008","question_text":"If the number of pilgrims who have visited at least one of the two shrines Kedarnath and Somnath is 165, then how many pilgrims visited only Kedarnath and Somnath?","options":{"A":"20","B":"30","C":"10","D":"15"},"correct_answer":"C","correct_answer_value":"10","solution_text":"Kedarnath+Somnath-both = 95+95-both=165 gives both(total)=25. Only-Kedarnath-Somnath = 25-15(all three) = 10.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8D_Q009","question_text":"If 180 pilgrims visited at least one of the two shrines Kedarnath or Badrinath, then how many pilgrims visited only Somnath?","options":{"A":"55","B":"40","C":"35","D":"60"},"correct_answer":"A","correct_answer_value":"55","solution_text":"Kedarnath+Badrinath-both=180 gives both(total)=20, so Kedarnath-Badrinath-only=5. Working through the remaining exactly-two and exactly-one totals gives only-Somnath = 55.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E8D_Q010","question_text":"If there is nobody who visited only Badrinath and Somnath, then how many people visited only Kedarnath?","options":{"A":"90","B":"80","C":"70","D":"50"},"correct_answer":"D","correct_answer_value":"50","solution_text":"With Badrinath-Somnath-only=0, the remaining two exactly-two components sum to 30, and Kedarnath's total (95=only-Kedarnath+Badrinath-Kedarnath-only+Kedarnath-Somnath-only+15) resolves to only-Kedarnath=50.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150}]},{"set_id":"LR_E8D_S11_14","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"Each of the students, residents of Kalpana Chawla Bhawan, likes at least one of four cool-drink brands -- Coca-cola, Thums-Up, Limca and Sprite. 65 students like Thums-Up and Coca-cola, 77 like Sprite and Thums-Up, 73 like Coca-cola and Limca, 76 like Sprite and Coca-cola (pairwise totals). 67 students like exactly one brand. The number who like only Limca, Thums-Up and Coca-cola equals the number who like only Sprite, Thums-Up and Coca-cola. The number who like Sprite, Limca and Thums-Up but not Coca-cola equals the number who like Sprite, Limca and Coca-cola but not Thums-Up. The number who like only Coca-cola and Sprite is 14. The numbers who like only Thums-Up and Coca-cola, and only Thums-Up and Limca, are 10 and 15 respectively. The sum of the number of students who like Thums-Up, Coca-cola, Sprite and Limca (each counted as a grand total) is 557.","setup_solution":"This is a four-set overlap problem with many pairwise and triple-overlap unknowns. Working through the given relations pins down most values, but the specific pairwise totals as transcribed do not all reconcile simultaneously (checked algebraically) -- see the type_specific note on this set. The values and answers below follow the provided answer key.","type_specific":{"note":"Solving this 4-set problem algebraically (treating the given pairwise totals, the two 'only-triple' equalities, the two named pair-only values 10 and 15, the exactly-one total of 67, and the grand-sum of 557 as a linear system) produces a genuine numerical contradiction regardless of which single figure is dropped -- the equations are consistently off by a small constant (effectively '192=193' in one reduction), pointing to a minor transcription slip of +/-1 in one of the many given numbers that could not be pinpointed from the image alone. The correct_answer values below match the provided answer key, and solution_text describes the intended method, but the intermediate figures are not independently self-consistent."},"entity_count":4,"variables":3,"constraints":10,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["algebraic_deduction","set_arithmetic"],"questions":[{"id":"LR_E8D_Q011","question_text":"How many students like both Sprite and Limca but not all the four?","options":{"A":"60","B":"50","C":"55","D":"44"},"correct_answer":"A","correct_answer_value":"60","solution_text":"Sprite-and-Limca-but-not-all-four = (Sprite-Limca-only) + (the two triples containing both Sprite and Limca), which works out to 60 per the answer key.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E8D_Q012","question_text":"What is the total number of students?","options":{"A":"247","B":"250","C":"235","D":"252"},"correct_answer":"D","correct_answer_value":"252","solution_text":"Summing exactly-one, exactly-two, exactly-three and all-four categories gives 252.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E8D_Q013","question_text":"How many students like only Coca-cola and Limca?","options":{"A":"16","B":"17","C":"13","D":"15"},"correct_answer":"C","correct_answer_value":"13","solution_text":"Only-Coca-cola-and-Limca = 13, per the answer key.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8D_Q014","question_text":"If 25 students like only Thums-Up or only Sprite, then how many like Coca-cola or Limca?","options":{"A":"42","B":"208","C":"152","D":"210"},"correct_answer":"D","correct_answer_value":"210","solution_text":"With only-Thums-Up plus only-Sprite fixed at 25, the Coca-cola-or-Limca total works out to 210.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180}]},{"set_id":"LR_E8D_S15_17","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"In a college library, four business newspapers -- Economic Times, Business Standard, Business Line and Financial Express -- are available. All students visit the library regularly but 20% do not read any business newspaper. The four newspapers (in that order) are read by 230, 180, 180 and 220 students respectively. The number of students reading exactly 2 newspapers for any two newspapers is 20. There are 30 students who read all four newspapers, but nobody reads exactly three of the four newspapers.","setup_solution":"With every pair-combination read by exactly 20 (6 pairs, aggregate exactly-two=120), exactly-three=0, and all-four=30: sum of enrollments (230+180+180+220=810) = exactly-one + 2x120 + 0 + 4x30, giving exactly-one=450. Total students N solves from exactly-one+exactly-two+all-four+none=N with none=0.2N: 450+120+30+0.2N=N, giving 0.8N=600, N=750.","entity_count":4,"variables":1,"constraints":5,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8D_Q015","question_text":"How many students do not read any newspaper at all?","options":{"A":"75","B":"100","C":"225","D":"150"},"correct_answer":"D","correct_answer_value":"150","solution_text":"None = 0.2 x 750 = 150.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8D_Q016","question_text":"What percentage of the people reading Business Standard also read at least one other newspaper?","options":{"A":"35%","B":"55%","C":"50%","D":"65%"},"correct_answer":"C","correct_answer_value":"50%","solution_text":"Each newspaper's total = only-that-paper + 90 (3 pairs x20 + all-four 30). Business Standard-only = 180-90=90, so those also reading another = 180-90=90, i.e. 50%.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8D_Q017","question_text":"If all the students in the college including those who do not read any newspaper read at least one newspaper (out of the four newspapers above) which he is not reading at present, then what is the least number of students reading all the four newspapers?","options":{"A":"60","B":"25","C":"15","D":"30"},"correct_answer":"D","correct_answer_value":"30","solution_text":"Since nobody currently reads exactly three newspapers, nobody can newly move into the all-four group by adding one more. The all-four count stays at its current value, 30.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180}]},{"set_id":"LR_E8D_S18_21","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"A survey of 300 respondents showed that 135 read Business India (BI), 125 read Business Today (BT) and 115 read Business World (BW). 42 read BI and BT, 48 read BT and BW, 43 read BI and BW, and 30 read all three magazines.","setup_solution":"Only-BI = 135-42-43+30=80. Only-BT = 125-42-48+30=65. Only-BW = 115-48-43+30=54. BI-BT-only=12, BT-BW-only=18, BI-BW-only=13.","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8D_Q018","question_text":"How many respondents read Business India or Business World?","options":{"A":"199","B":"272","C":"207","D":"175"},"correct_answer":"C","correct_answer_value":"207","solution_text":"BI-union-BW = 135+115-43 = 207.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E8D_Q019","question_text":"If seven of the respondents who were previously reading only Business India now start reading a second magazine also and five of the respondents who were previously reading only Business India now stop even that, then how many respondents read Business India now?","options":{"A":"75","B":"132","C":"142","D":"130"},"correct_answer":"D","correct_answer_value":"130","solution_text":"The 7 who add a second magazine still read BI (no change to the BI count). The 5 who stop entirely leave the BI-reading group: 135-5=130.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8D_Q020","question_text":"If 15 respondents who were reading Business India stop reading Business India and start reading Business Today, then what is the maximum number of respondents who will now be reading only Business India?","options":{"A":"120","B":"65","C":"78","D":"93"},"correct_answer":"C","correct_answer_value":"78","solution_text":"Only respondents not already reading BT are eligible to 'start' BT: only-BI(80) and BI-BW-only(13), totaling 93. To maximize the surviving only-BI count, draw from BI-BW-only first (13), then 2 more must come from only-BI: 80-2=78.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E8D_Q021","question_text":"If 16 of the respondents, who were reading Business Today, stop reading Business Today and instead start reading Business World, then what is the maximum number of respondents who will now be reading Business India and Business World?","options":{"A":"59","B":"55","C":"75","D":"63"},"correct_answer":"B","correct_answer_value":"55","solution_text":"Only respondents not already reading BW are eligible: only-BT(65) and BI-BT-only(12). To maximize the new BI-BW total, draw all 12 from BI-BT-only (each conversion adds one to BI-BW), and the remaining 4 from only-BT (no effect). New BI-BW total = 43+12 = 55.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180}]},{"set_id":"LR_E8D_S22_24","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"In a colony, a survey was conducted regarding ownership of three vehicles -- car, scooter and bicycle. The number of residents owning all three vehicles is the same as those owning none. The number of residents owning any two out of the three vehicles is the same as those owning any other two, which in turn is the same as those owning none of the three. The number of residents owning scooters alone is the same as those owning cars alone, and each in turn is twice those owning bicycles alone. Half of the number of residents who own a bicycle also own at least one of the other two vehicles.","setup_solution":"Let k = none = all-three = each of the three exactly-two categories. Let onlyBicycle=b, onlyCar=onlyScooter=2b. Since half of bicycle owners own only a bicycle, onlyBicycle=Bicycle_total/2, and Bicycle_total=b+3k, giving b=3k. Total = 2b+2b+b+4k = 5b+4k... (reconciled per-question using k and b=3k).","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"multiple","information_load":"high","solving_methodologies":["algebraic_deduction","set_arithmetic"],"questions":[{"id":"LR_E8D_Q022","question_text":"If the number of residents who own only bicycles is 150, then what is the total number of residents in the colony?","options":{"A":"500","B":"1000","C":"750","D":"1250"},"correct_answer":"B","correct_answer_value":"1000","solution_text":"b=150=3k gives k=50. Total = 5b+5k = 750+250 = 1000.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8D_Q023","question_text":"If 15 residents do not own any of the three vehicles, then how many residents are there?","options":{"A":"100","B":"200","C":"500","D":"300"},"correct_answer":"D","correct_answer_value":"300","solution_text":"k=15. Total = 20k = 300.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":120},{"id":"LR_E8D_Q024","question_text":"What percentage of the residents own a scooter or a car but not a bicycle?","options":{"A":"65%","B":"55%","C":"75%","D":"45%"},"correct_answer":"A","correct_answer_value":"65%","solution_text":"Scooter-or-car-not-bicycle = 2b+2b+k(car-scooter-only) = 13k, out of Total=20k, giving 65%.","question_operation":"numerical_computation","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150}]},{"set_id":"LR_E8D_S25_27","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"In the diagram, the Circle represents people who are Hindus, the Triangle represents members of a club, the Quadrilateral represents Actors, and the Hexagon represents people whose mother tongue is Hindi.","setup_solution":"Reading the diagram: region h is the overlap common to all four shapes (Hindu, club member, actor, Hindi mother tongue). Regions g and k lie within the Triangle and Quadrilateral but outside the Circle. Region i lies within the Circle only, outside the Triangle, Quadrilateral and Hexagon.","entity_count":12,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["diagram_region_reading"],"questions":[{"id":"LR_E8D_Q025","question_text":"Which of the following represents the people who are Hindus, club members, actors and whose mother tongue is Hindi?","options":{"A":"i","B":"h","C":"j","D":"d"},"correct_answer":"B","correct_answer_value":"h","solution_text":"Region h is the unique overlap of all four shapes.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8D_S25_27"},{"id":"LR_E8D_Q026","question_text":"Which of the following represents the people who are not Hindus but are members of a club and actors?","options":{"A":"g, c","B":"c, a","C":"g, k","D":"c, g, a"},"correct_answer":"C","correct_answer_value":"g, k","solution_text":"Regions g and k both lie within the Triangle (club) and Quadrilateral (Actors) but outside the Circle (Hindu).","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8D_S25_27"},{"id":"LR_E8D_Q027","question_text":"Which of the following represents the people, who are Hindu but are not the members of a club, are not actors and whose mother tongue is not Hindi?","options":{"A":"j","B":"a","C":"f","D":"i"},"correct_answer":"D","correct_answer_value":"i","solution_text":"Region i lies inside the Circle (Hindu) only, outside the Triangle, Quadrilateral and Hexagon.","question_operation":"position_lookup","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90,"question_image":"QIMG_LR_E8D_S25_27"}],"question_image":"QIMG_LR_E8D_S25_27"},{"set_id":"LR_E8D_S28_30","exercise":"exercise_8d","type":"venn_diagrams","is_set":true,"setup_text":"A survey was conducted among 300 Room air conditioner owners. It was found that 125 people had Carrier Aircon, 145 people had Voltas and 90 people had Fedders Lloyd air conditioners with them. Thirty two of them had exactly two out of the three brands of air conditioners, and each person owns at least one of the three brands.","setup_solution":"Total=125+145+90-(sum of pairwise totals)+T=300, and exactly-two=(sum of pairwise totals)-3T=32, so sum of pairwise totals=32+3T. Substituting: 360-(32+3T)+T=300, giving 328-2T=300, T(all three)=14.","entity_count":3,"variables":1,"constraints":4,"case_splits":1,"resolution_type":"multiple","information_load":"high","solving_methodologies":["set_arithmetic","algebraic_deduction"],"questions":[{"id":"LR_E8D_Q028","question_text":"If six owners had only Voltas and Fedders Lloyd air conditioners with them, then how many have only Carrier Aircon with them?","options":{"A":"125","B":"65","C":"45","D":"85"},"correct_answer":"D","correct_answer_value":"85","solution_text":"With Voltas-Fedders-only=6, the other two exactly-two components (Carrier-Voltas-only + Carrier-Fedders-only) sum to 32-6=26. Only-Carrier = 125-14-26 = 85.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8D_Q029","question_text":"If 110 owners had only Voltas air conditioners, then how many have only Carrier Aircon and Fedders Lloyd with them?","options":{"A":"11","B":"17","C":"8","D":"23"},"correct_answer":"A","correct_answer_value":"11","solution_text":"Only-Voltas=110 gives (Carrier-Voltas-only + Voltas-Fedders-only)=145-110-14=21. Since exactly-two totals 32, Carrier-Fedders-only = 32-21 = 11.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":150},{"id":"LR_E8D_Q030","question_text":"If ten of the owners having only Carrier Aircon now buy Voltas also, and 5 of the owners who had only Voltas and Fedders Lloyd now buy Carrier Aircon also, then how many have at least two out of the three brands of air conditioners?","options":{"A":"19","B":"61","C":"56","D":"73"},"correct_answer":"C","correct_answer_value":"56","solution_text":"10 owners move from exactly-one to exactly-two (exactly-two: 32+10=42... then 5 owners move from exactly-two to all-three: exactly-two becomes 42-5=37, all-three becomes 14+5=19). At-least-two = 37+19 = 56.","question_operation":"hypothetical","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180}]}]`);export{e as default};
